from autor import Lectie, Expeditie, Unitate, grafic

REF = "Manual Art Klett, clasa a V-a (manuale.edu.ro), lecția „{}”"
S_AER = ["NASA Earth Observatory – Earth's Atmosphere", "Wikipedia – Atmosphere of Earth (compoziția aerului uscat)"]
S_STRAT = ["NOAA / National Weather Service JetStream – Layers of the Atmosphere", "UCAR Center for Science Education – Layers of Earth's Atmosphere"]
S_WMO = ["WMO – World Weather and Climate Extremes Archive", "NOAA NCEI – Global extremes"]
S_RO = ["Administrația Națională de Meteorologie (ANM) – extreme climatice", "Wikipedia – Climate of Romania"]
RS = (45.38, 27.05)  # Râmnicu Sărat


def unitate():
    # ================================================================ S17 Atmosfera: caracteristici generale
    A = Lectie(5, "V-S17-caracteristici-generale-importanta", "Atmosfera – caracteristici generale și importanță",
               "De ce nu poți vedea aerul, dar îl simți când bate vântul?",
               [("Ce este atmosfera", "Atmosfera este învelișul de aer care înconjoară Pământul. Este ținută lângă planetă de atracția gravitațională.\nAerul este un amestec de gaze: în cea mai mare parte azot (aproximativ 78 %) și oxigen (aproximativ 21 %). Restul de 1 % înseamnă argon, dioxid de carbon, vapori de apă și alte gaze."),
                ("Straturile atmosferei", "De jos în sus: troposfera, stratosfera, mezosfera, termosfera și exosfera.\nTroposfera e stratul în care trăim. Are aproximativ 8 km grosime la poli și 16–18 km la Ecuator. Aici se formează norii, ploile și vânturile. Pe măsură ce urci în troposferă, aerul se răcește.\nÎn stratosferă se află stratul de ozon, care oprește o parte din razele ultraviolete ale Soarelui."),
                ("De ce e importantă atmosfera", "Ne dă oxigenul pentru respirație și dioxidul de carbon pentru plante.\nNe apără de razele dăunătoare ale Soarelui și de meteoriții mici, care ard în ea (stelele căzătoare).\nPăstrează căldura: fără atmosferă, nopțile ar fi foarte geroase, iar zilele foarte fierbinți, ca pe Lună.")],
               stiaica="„Stelele căzătoare” nu sunt stele: sunt bucăți mici de rocă din spațiu care ard când intră cu viteză mare în atmosferă.",
               ref=REF.format("Atmosfera – caracteristici generale și importanță"))
    A.a(1, "1.1", "Ce este atmosfera?", "învelișul de aer al Pământului", ["învelișul de apă al Pământului", "stratul de roci de la suprafață", "totalitatea viețuitoarelor"], "Atmosfera = învelișul de aer; hidrosfera = apa; litosfera = rocile; biosfera = viețuitoarele.")
    A.a(1, "1.1", "Ce gaz se găsește în cea mai mare cantitate în aer?", "azotul", ["oxigenul", "dioxidul de carbon", "hidrogenul"], "Aerul conține aproximativ 78 % azot și 21 % oxigen.", surse=S_AER)
    A.a(1, "3.3", "Ce gaz din aer respirăm ca să trăim?", "oxigenul", ["azotul", "argonul", "heliul"], "Oamenii și animalele au nevoie de oxigen.")
    A.a(2, "3.3", "Ce gaz din aer folosesc plantele ca să-și producă hrana?", "dioxidul de carbon", ["azotul", "argonul", "ozonul"], "Plantele iau dioxid de carbon și eliberează oxigen.")
    A.g(2, "2.3 3.1", "Graficul arată compoziția aerului uscat. Ce procent are oxigenul?", grafic("structura", "Compoziția aerului uscat", [("azot", 78), ("oxigen", 21), ("argon și alte gaze", 1)], "%", "NASA Earth Observatory"), "aproximativ 21 %", ["aproximativ 78 %", "aproximativ 1 %", "aproximativ 50 %"], "Oxigenul are aproximativ 21 %; azotul aproximativ 78 %.", surse=S_AER)
    A.o(2, "1.1", "Ordonează straturile atmosferei de jos în sus.", ["troposfera", "stratosfera", "mezosfera", "termosfera", "exosfera"], "De la sol spre spațiu", "Tro-, strato-, mezo-, termo-, exosfera.", surse=S_STRAT)
    A.a(1, "1.1", "În ce strat al atmosferei trăim?", "troposfera", ["stratosfera", "exosfera", "mezosfera"], "Troposfera e stratul de lângă sol.")
    A.a(2, "1.2", "În ce strat al atmosferei se formează norii și ploile?", "troposfera", ["stratosfera", "termosfera", "exosfera"], "Aproape toți vaporii de apă sunt în troposferă, deci și norii.", surse=S_STRAT)
    A.a(2, "1.1", "În ce strat se află stratul de ozon?", "stratosfera", ["troposfera", "mezosfera", "exosfera"], "Stratul de ozon e în stratosferă.", surse=S_STRAT)
    A.a(2, "3.3", "Ce face stratul de ozon pentru noi?", "oprește o parte din razele ultraviolete dăunătoare ale Soarelui", ["produce ploile", "aduce oxigenul", "încălzește oceanele"], "Ozonul ne apără pielea și ochii de razele ultraviolete.")
    A.a(2, "3.1", "Cât de groasă este troposfera la Ecuator?", "aproximativ 16–18 km", ["aproximativ 1 km", "aproximativ 100 km", "aproximativ 500 km"], "Troposfera are aproximativ 8 km la poli și 16–18 km la Ecuator.", surse=S_STRAT)
    A.a(3, "1.2", "De ce troposfera e mai groasă la Ecuator decât la poli?", "pentru că aerul cald de la Ecuator se dilată și urcă mai sus", ["pentru că la Ecuator sunt mai mulți munți", "pentru că la poli nu există aer", "pentru că Luna trage aerul spre Ecuator"], "Aerul încălzit se dilată și urcă: de aceea troposfera e mai înaltă la Ecuator.")
    A.adev(2, "3.2", "Cu cât urci mai sus în troposferă, cu atât aerul e mai rece.", True, "Adevărat: de aceea pe vârfurile munților e mai frig și stă zăpada.")
    A.adev(1, "1.2", "Aerul este format dintr-un singur gaz.", False, "Fals: aerul e un amestec de gaze, mai ales azot și oxigen.")
    A.adev(2, "3.3", "Fără atmosferă, pe Pământ ar fi mult mai mari diferențele de temperatură dintre zi și noapte.", True, "Adevărat: atmosfera păstrează căldura, ca o pătură.")
    A.s(2, "1.1", "Asociază învelișul Pământului cu ce conține.", [("atmosfera", "aer"), ("hidrosfera", "apă"), ("litosfera", "roci"), ("biosfera", "viețuitoare")], "Cele patru învelișuri ale Pământului.")
    A.s(2, "3.3", "Asociază rolul atmosferei cu exemplul.", [("ne dă aerul de respirat", "oxigenul"), ("ne apără de razele Soarelui", "stratul de ozon"), ("ne apără de meteoriți", "stelele căzătoare ard în aer"), ("păstrează căldura", "nopți mai puțin reci")], "Atmosfera are mai multe roluri importante.")
    A.l(1, "1.1", "Completează.", "Aerul conține aproximativ 78 % [azot] și 21 % [oxigen].", ["heliu", "hidrogen"], "Azotul și oxigenul formează aproape tot aerul.", surse=S_AER)
    A.l(2, "1.1", "Completează.", "Stratul de jos al atmosferei, în care trăim, se numește [troposferă]; deasupra lui se află [stratosfera].", ["exosfera", "litosfera"], "Troposfera, apoi stratosfera.")
    A.a(2, "3.2", "Ce sunt „stelele căzătoare”?", "meteoriți mici care ard când intră în atmosferă", ["stele care cad pe Pământ", "avioane", "fulgere"], "Frecarea cu aerul îi încălzește până ard.")
    A.a(3, "4.1", "Cum poți arăta că aerul ocupă loc?", "împingi un pahar gol, cu gura în jos, într-un vas cu apă: apa nu intră în pahar", ["pui paharul la soare", "scrii pe pahar", "spargi paharul"], "Aerul prins în pahar nu lasă apa să intre.")
    A.a(3, "4.1", "Un balon umflat pus la frigider se micșorează. Ce arată experimentul?", "aerul rece ocupă mai puțin loc decât aerul cald", ["aerul dispare la frig", "balonul se topește", "aerul devine apă"], "Aerul se contractă la rece și se dilată la cald.")
    A.a(2, "3.3", "Ce poluează aerul?", "fumul de la fabrici, mașini și arderea gunoaielor", ["plantele verzi", "ploaia", "zăpada"], "Gazele și particulele din arderi poluează aerul.")
    A.a(2, "4.3", "Ce poți face tu pentru un aer mai curat?", "mergi pe jos sau cu bicicleta pe distanțe mici și nu arzi frunze sau gunoaie", ["lași motorul mașinii pornit", "arzi plasticul în curte", "tai copacii din parc"], "Mai puține arderi înseamnă aer mai curat.")
    A.a(3, "1.2", "Pe Lună nu există atmosferă. Ce urmare are?", "cerul e negru și ziua, iar temperatura variază enorm între zi și noapte", ["cerul e albastru", "plouă des", "bat vânturi puternice"], "Fără aer nu există nori, vânt, ploaie, iar căldura nu e păstrată.")
    A.a(2, "3.2", "De ce e mai greu să respiri pe un munte foarte înalt?", "pentru că aerul e mai rarefiat (mai puțin dens), deci primești mai puțin oxigen la fiecare respirație", ["pentru că acolo nu există oxigen deloc", "pentru că e prea cald", "pentru că aerul e mai umed"], "Sus, aerul e mai rar; alpiniștii de pe Everest folosesc des butelii cu oxigen.")
    A.o(3, "3.2", "Ordonează locurile de la cel mai cald la cel mai rece, într-o zi de vară, în aceeași zonă.", ["câmpia de la poalele muntelui", "dealul", "pădurea de pe munte", "vârful muntelui"], "De la cald la rece", "Temperatura scade cu altitudinea în troposferă.")
    A.a(2, "1.1", "Care strat al atmosferei e cel mai îndepărtat de Pământ?", "exosfera", ["troposfera", "stratosfera", "mezosfera"], "Exosfera trece treptat în spațiul cosmic.", surse=S_STRAT)
    A.a(2, "3.3", "Cum se numește amestecul de ceață și fum care apare deasupra orașelor foarte poluate?", "smog", ["brumă", "polei", "rouă"], "Smog vine din englezescul smoke (fum) + fog (ceață).")
    A.a(3, "3.3", "De ce în orașele mari se pun stații de măsurare a calității aerului?", "ca oamenii să afle când aerul e poluat și să se protejeze", ["ca să măsoare înălțimea clădirilor", "ca să facă ploaie", "ca să numere mașinile"], "Datele despre aer ajută la protejarea sănătății.")

    # ================================================================ S18 Elemente și fenomene meteorologice
    M = Lectie(5, "V-S18-elemente-fenomene-meteorologice", "Elemente și fenomene meteorologice",
               "Cum știu meteorologii dacă mâine va ploua?",
               [("Elementele meteorologice", "Starea atmosferei se descrie prin elementele meteorologice: temperatura aerului, presiunea atmosferică, umezeala, nebulozitatea (cât e cerul acoperit de nori), vântul și precipitațiile.\nLe măsurăm la stațiile meteorologice, cu instrumente: termometrul (temperatura), barometrul (presiunea), higrometrul (umezeala), anemometrul (viteza vântului), girueta (direcția vântului), pluviometrul (precipitațiile)."),
                ("Temperatura și presiunea", "Aerul e încălzit mai ales de suprafața Pământului, care primește căldura de la Soare. Temperatura se măsoară în grade Celsius (°C), la umbră, la 2 m de sol.\nPresiunea atmosferică este apăsarea aerului pe suprafața Pământului. Ea scade cu altitudinea. Aerul se mișcă de la presiune mare spre presiune mică: așa se formează vântul."),
                ("Nori, precipitații, fenomene", "Când aerul umed se răcește, vaporii de apă se transformă în picături mici: se formează norii și ceața.\nPrecipitațiile sunt apa care cade din nori: ploaie, zăpadă, lapoviță, grindină.\nFenomene meteorologice: ceața, roua, bruma, poleiul, chiciura, oraje (fulgere și tunete), vijelii, viscolul, curcubeul.")],
               stiaica="Pentru că lumina ajunge la noi aproape instantaneu, iar sunetul parcurge aproximativ 1 km în 3 secunde, poți afla cât de departe e o furtună: numără secundele dintre fulger și tunet și împarte la 3.",
               ref=REF.format("Elemente și fenomene meteorologice"))
    M.s(1, "1.1", "Asociază instrumentul cu ce măsoară.", [("termometrul", "temperatura"), ("barometrul", "presiunea atmosferică"), ("pluviometrul", "precipitațiile"), ("anemometrul", "viteza vântului")], "Fiecare element meteorologic are instrumentul lui.")
    M.a(1, "1.1", "Cu ce instrument se măsoară temperatura aerului?", "termometrul", ["barometrul", "pluviometrul", "busola"], "Termometrul măsoară temperatura, în grade Celsius.")
    M.a(2, "1.1", "Ce arată girueta?", "direcția din care bate vântul", ["cantitatea de ploaie", "temperatura", "presiunea"], "Girueta se întoarce cu vârful spre locul de unde vine vântul.")
    M.a(2, "1.1", "Ce măsoară higrometrul?", "umezeala aerului", ["viteza vântului", "presiunea", "temperatura apei"], "Higrometrul arată câți vapori de apă are aerul.")
    M.a(1, "2.2", "În ce unitate de măsură se exprimă temperatura aerului la noi?", "grade Celsius (°C)", ["kilometri", "litri", "kilograme"], "Temperatura se exprimă în °C.")
    M.a(2, "2.2", "În ce unitate se măsoară cantitatea de precipitații?", "litri pe metru pătrat (l/m²) sau milimetri", ["grade Celsius", "kilometri pe oră", "kilograme"], "1 l/m² = un strat de apă de 1 mm.")
    M.a(2, "1.2", "Unde se măsoară corect temperatura aerului?", "la umbră, la 2 m deasupra solului, într-un adăpost meteorologic", ["în plin soare, pe asfalt", "în casă, lângă calorifer", "în apa râului"], "Termometrul pus la soare arată mai mult decât temperatura reală a aerului.")
    M.a(2, "1.2", "Ce este vântul?", "deplasarea aerului de la o zonă cu presiune mare spre una cu presiune mică", ["căderea apei din nori", "apa care se evaporă", "lumina Soarelui"], "Diferențele de presiune pun aerul în mișcare.")
    M.a(2, "3.2", "Ce se întâmplă cu presiunea atmosferică pe măsură ce urci pe munte?", "scade", ["crește", "rămâne la fel", "devine zero la 1 000 m"], "Deasupra ta e tot mai puțin aer, deci apasă mai puțin.")
    M.a(2, "1.2", "Cum se formează norii?", "aerul umed urcă, se răcește, iar vaporii de apă se transformă în picături foarte mici", ["din fumul fabricilor", "din praf", "din gheața de la poli"], "Răcirea aerului umed produce condensarea vaporilor.")
    M.s(2, "1.1", "Asociază tipul de precipitații cu descrierea.", [("ploaia", "picături de apă"), ("zăpada", "fulgi de gheață"), ("grindina", "bucăți rotunde de gheață, vara, la furtuni"), ("lapovița", "amestec de ploaie și zăpadă")], "Forma precipitațiilor depinde de temperatura aerului.")
    M.s(2, "1.1", "Asociază fenomenul cu descrierea.", [("roua", "picături de apă pe iarbă, dimineața"), ("bruma", "cristale fine de gheață pe iarbă, toamna"), ("poleiul", "strat de gheață pe drum, din ploaie care îngheață"), ("ceața", "nor la nivelul solului")], "Toate apar când aerul umed se răcește.")
    M.a(2, "1.2", "Ce fenomen apare când ploaia cade pe sol înghețat și formează gheață?", "poleiul", ["roua", "curcubeul", "seceta"], "Poleiul face drumurile foarte alunecoase.")
    M.a(2, "1.2", "Când apare curcubeul?", "când Soarele luminează picăturile de ploaie, iar noi stăm cu spatele la Soare", ["noaptea, pe cer senin", "doar iarna", "doar la Ecuator"], "Picăturile descompun lumina albă în culori.")
    M.a(3, "3.1", "Vezi fulgerul, iar tunetul se aude după 9 secunde. Cam la ce distanță e furtuna?", "aproximativ 3 km", ["aproximativ 9 km", "aproximativ 30 km", "aproximativ 300 m"], "Sunetul parcurge aproximativ 1 km în 3 secunde: 9 : 3 = 3 km.")
    M.a(2, "1.1", "Ce înseamnă nebulozitate?", "cât din cer e acoperit de nori", ["cât de tare bate vântul", "cât de cald e", "câtă apă e în râuri"], "Cer senin, noros sau acoperit: așa descriem nebulozitatea.")
    M.adev(1, "1.2", "Grindina cade mai ales vara, din norii de furtună.", True, "Adevărat: în norii de furtună picăturile urcă sus, îngheață și cad ca grindină.")
    M.adev(2, "1.2", "Aerul este încălzit direct și mai ales de razele Soarelui care trec prin el.", False, "Fals: razele încălzesc mai întâi solul și apa, iar acestea încălzesc aerul de deasupra.")
    M.adev(2, "3.2", "Aerul cald este mai ușor și urcă.", True, "Adevărat: de aceea balonul cu aer cald zboară.")
    M.l(2, "1.1", "Completează.", "Presiunea atmosferică se măsoară cu [barometrul], iar viteza vântului cu [anemometrul].", ["pluviometrul", "termometrul"], "Barometru – presiune; anemometru – vânt.")
    M.l(2, "1.2", "Completează.", "Apa care cade din nori se numește [precipitații]; norul care stă chiar lângă sol se numește [ceață].", ["rouă", "vânt"], "Ceața e un nor la nivelul solului.")
    M.g(2, "2.3", "Graficul arată temperatura aerului într-o zi de vară, la o stație imaginară. La ce oră a fost cel mai cald?", grafic("profil", "Temperatura aerului într-o zi de vară (date imaginare)", [("ora 6", 16), ("ora 9", 21), ("ora 12", 27), ("ora 15", 30), ("ora 18", 26), ("ora 21", 20)], "°C"), "la ora 15", ["la ora 12", "la ora 6", "la ora 21"], "Cel mai cald e după-amiaza, după ce solul s-a încălzit toată dimineața.")
    M.g(3, "2.3 3.1", "În aceeași zi imaginară, cu câte grade a crescut temperatura de la ora 6 la ora 15?", grafic("profil", "Temperatura aerului într-o zi de vară (date imaginare)", [("ora 6", 16), ("ora 9", 21), ("ora 12", 27), ("ora 15", 30), ("ora 18", 26), ("ora 21", 20)], "°C"), "cu 14 grade", ["cu 30 de grade", "cu 16 grade", "cu 10 grade"], "30 − 16 = 14 grade. Diferența dintre maxima și minima unei zile se numește amplitudine diurnă.")
    M.g(2, "2.3", "Graficul arată precipitațiile dintr-o săptămână, la o stație imaginară. În ce zi a plouat cel mai mult?", grafic("bare", "Precipitații într-o săptămână (date imaginare)", [("luni", 0), ("marți", 12), ("miercuri", 3), ("joi", 25), ("vineri", 0), ("sâmbătă", 6), ("duminică", 1)], "l/m²"), "joi", ["marți", "luni", "duminică"], "Joi bara e cea mai înaltă: 25 l/m².")
    M.o(2, "1.2", "Ordonează pașii prin care se formează ploaia.", ["Soarele încălzește apa", "apa se evaporă", "aerul umed urcă și se răcește", "se formează norii", "picăturile cresc și cad ca ploaie"], "Ordinea formării ploii", "Evaporare, urcare, răcire, condensare, precipitații.")
    M.a(2, "4.3", "Ce faci dacă te prinde furtuna cu fulgere pe un câmp?", "te depărtezi de copacii singuratici și de stâlpi și te ghemuiești jos, pe vine", ["te adăpostești sub cel mai înalt copac", "ridici o umbrelă metalică", "urci pe un deal"], "Fulgerul lovește des obiectele înalte, izolate.")
    M.a(3, "1.2", "Seara e senin și nu bate vântul; dimineață, pe iarbă sunt picături de apă. Ce s-a format?", "rouă", ["polei", "grindină", "chiciură"], "Noaptea senină răcește solul, iar vaporii se depun ca rouă.")
    M.a(3, "3.2", "De ce iarna, la ger, se formează chiciură pe crengi?", "pentru că ceața sau vaporii îngheață direct pe ramurile foarte reci", ["pentru că plouă cu gheață", "pentru că bate vântul cald", "pentru că se topește zăpada"], "Chiciura apare pe vreme geroasă și cu ceață.")
    M.a(2, "1.1", "Cum se numește clădirea sau terenul unde se măsoară zilnic elementele meteorologice?", "stația meteorologică", ["observatorul astronomic", "stația de pompare", "hidrocentrala"], "La stațiile meteorologice se fac măsurători la ore fixe.")
    M.a(2, "1.2", "Ce aduce de obicei scăderea bruscă a presiunii atmosferice?", "vreme rea, cu nori și precipitații", ["cer senin și ger", "nimic, presiunea nu contează", "secetă"], "Presiunea joasă e asociată cu aer care urcă, nori și ploi.")
    M.a(1, "1.1", "Ce fenomen e format din fulgere și tunete?", "orajul", ["poleiul", "bruma", "roua"], "Orajele (furtunile cu descărcări electrice) apar mai ales vara.")

    # ================================================================ S19 Vremea și clima
    V = Lectie(5, "V-S19-vremea-clima", "Vremea și clima",
               "Dacă azi ninge la Râmnicu Sărat, înseamnă că avem o climă rece?",
               [("Vremea", "Vremea este starea atmosferei într-un loc, la un moment dat sau pe o perioadă scurtă (ore, zile). Se schimbă des: dimineața poate fi senin, iar după-amiaza ploaie.\nPrognoza meteo anunță cum va fi vremea în zilele următoare; în România o face Administrația Națională de Meteorologie (ANM)."),
                ("Clima", "Clima este regimul vremii dintr-un loc, observat pe o perioadă foarte lungă (de obicei cel puțin 30 de ani).\nClima unui loc depinde de: latitudine (cât de aproape e de Ecuator), altitudine, apropierea de mare sau ocean, relief, curenții oceanici și vânturile care bat des."),
                ("Diagrama climatică", "Clima se arată printr-o diagramă climatică: pentru fiecare lună, coloane albastre pentru precipitații și o linie roșie pentru temperatura medie.\nDin ea afli luna cea mai caldă, luna cea mai rece și luna cea mai ploioasă.")],
               stiaica="Cea mai mare temperatură măsurată oficial în România a fost de 44,5 °C, la Ion Sion (județul Brăila), pe 10 august 1951, după datele ANM.",
               ref=REF.format("Vremea și clima"))
    V.a(1, "1.1", "Ce este vremea?", "starea atmosferei într-un loc, pe o perioadă scurtă", ["regimul vremii pe zeci de ani", "forma de relief", "cantitatea de apă din râu"], "Vremea e „acum” sau „zilele acestea”.")
    V.a(1, "1.1", "Ce este clima?", "regimul vremii dintr-un loc, observat pe o perioadă foarte lungă", ["vremea de azi", "un nor mare", "temperatura de la ora 12"], "Clima se stabilește din observații de cel puțin 30 de ani.")
    V.a(2, "1.2", "Ce propoziție vorbește despre climă, nu despre vreme?", "„În Sahara plouă foarte rar.”", ["„Azi ninge la Buzău.”", "„Mâine va fi vânt puternic.”", "„Acum e 25 °C.”"], "Despre Sahara se spune ce se întâmplă în mod obișnuit, de-a lungul anilor: asta e clima.")
    V.a(2, "1.2", "Ce propoziție vorbește despre vreme?", "„Diseară va ploua cu descărcări electrice.”", ["„La Polul Sud e frig tot anul.”", "„La Ecuator e cald și umed tot anul.”", "„Iernile la munte sunt lungi.”"], "Ploaia de diseară e un moment scurt: vremea.")
    V.a(2, "1.1", "Ce instituție face prognoza vremii în România?", "Administrația Națională de Meteorologie (ANM)", ["Ministerul Sportului", "Primăria", "Agenția Spațială Europeană"], "ANM emite prognoze și avertizări (coduri galben, portocaliu, roșu).")
    V.s(2, "3.2", "Asociază factorul cu efectul lui asupra climei.", [("latitudinea", "mai aproape de Ecuator, mai cald"), ("altitudinea", "mai sus, mai rece"), ("apropierea de ocean", "veri răcoroase, ierni blânde"), ("depărtarea de ocean", "veri fierbinți, ierni geroase, puține ploi")], "Factorii care influențează clima.")
    V.a(2, "3.2", "De ce e mai frig pe vârful Omu decât la Buzău, în aceeași zi?", "pentru că vârful e mult mai sus, iar temperatura scade cu altitudinea", ["pentru că e mai aproape de Polul Nord", "pentru că nu bate Soarele acolo", "pentru că e lângă mare"], "Altitudinea face diferența.")
    V.a(2, "3.2", "De ce e mai cald la Ecuator decât la poli?", "pentru că la Ecuator razele Soarelui cad aproape perpendicular", ["pentru că Ecuatorul e mai aproape de Soare cu mii de kilometri", "pentru că la poli nu există aer", "pentru că la Ecuator sunt vulcani"], "Razele perpendiculare încălzesc mai tare o suprafață mai mică.")
    V.a(3, "3.2", "Două orașe sunt la aceeași latitudine. Unul e pe țărmul oceanului, celălalt în mijlocul continentului. Care are iernile mai blânde?", "orașul de pe țărm", ["orașul din mijlocul continentului", "au ierni identice", "niciunul nu are iarnă"], "Oceanul se încălzește și se răcește încet, așa că îndulcește iernile.")
    V.g(2, "2.3", "Diagrama arată temperatura medie lunară la o stație imaginară. Care e luna cea mai caldă?", grafic("profil", "Temperatura medie lunară (date imaginare)", [("I", -3), ("II", -1), ("III", 5), ("IV", 11), ("V", 17), ("VI", 21), ("VII", 23), ("VIII", 22), ("IX", 17), ("X", 11), ("XI", 5), ("XII", 0)], "°C"), "iulie", ["ianuarie", "mai", "octombrie"], "Linia atinge cel mai sus punct în iulie: 23 °C.")
    V.g(2, "2.3", "La aceeași stație imaginară, care e luna cea mai rece?", grafic("profil", "Temperatura medie lunară (date imaginare)", [("I", -3), ("II", -1), ("III", 5), ("IV", 11), ("V", 17), ("VI", 21), ("VII", 23), ("VIII", 22), ("IX", 17), ("X", 11), ("XI", 5), ("XII", 0)], "°C"), "ianuarie", ["iulie", "martie", "decembrie"], "Cel mai jos punct e în ianuarie: −3 °C.")
    V.g(3, "2.3 3.1", "Care e diferența dintre luna cea mai caldă și luna cea mai rece la stația imaginară (amplitudinea anuală)?", grafic("profil", "Temperatura medie lunară (date imaginare)", [("I", -3), ("II", -1), ("III", 5), ("IV", 11), ("V", 17), ("VI", 21), ("VII", 23), ("VIII", 22), ("IX", 17), ("X", 11), ("XI", 5), ("XII", 0)], "°C"), "26 °C", ["20 °C", "23 °C", "3 °C"], "23 − (−3) = 23 + 3 = 26 °C.", ind="Scăzând un număr negativ, de fapt aduni.")
    V.g(2, "2.3", "Diagrama arată precipitațiile lunare la o stație imaginară. Care e luna cea mai ploioasă?", grafic("bare", "Precipitații medii lunare (date imaginare)", [("I", 30), ("II", 28), ("III", 32), ("IV", 45), ("V", 65), ("VI", 85), ("VII", 70), ("VIII", 55), ("IX", 40), ("X", 35), ("XI", 38), ("XII", 33)], "l/m²"), "iunie", ["ianuarie", "august", "decembrie"], "Bara cea mai înaltă e la iunie: 85 l/m². La noi, cele mai multe ploi cad la începutul verii.")
    V.adev(2, "1.2", "Vremea se schimbă de la o zi la alta, dar clima unui loc rămâne aproape aceeași de la un an la altul.", True, "Adevărat: vremea e schimbătoare, clima e regimul obișnuit.")
    V.adev(2, "1.2", "Dacă într-o zi de iulie e frig la Râmnicu Sărat, înseamnă că avem o climă polară.", False, "Fals: o zi rece e vremea, nu clima.")
    V.l(2, "1.1", "Completează.", "Starea atmosferei pe termen scurt se numește [vreme]; regimul ei pe o perioadă lungă se numește [climă].", ["prognoză", "presiune"], "Vreme – scurt; climă – lung.")
    V.l(2, "2.3", "Completează.", "Pe diagrama climatică, temperatura se reprezintă cu o [linie] roșie, iar precipitațiile cu [coloane] albastre.", ["săgeți", "puncte"], "Linie pentru temperatură, coloane pentru precipitații.")
    V.a(2, "4.3", "Ce înseamnă o avertizare meteo de cod roșu?", "fenomene meteorologice foarte periculoase; trebuie urmate instrucțiunile autorităților", ["vreme frumoasă", "o zi liberă oricum", "doar ploaie slabă"], "Codurile, de la galben la roșu, arată pericolul tot mai mare.")
    V.o(2, "4.3", "Ordonează codurile de avertizare meteo de la cel mai puțin periculos la cel mai periculos.", ["cod galben", "cod portocaliu", "cod roșu"], "De la mic la mare pericol", "Galben, portocaliu, roșu.")
    V.a(3, "3.2", "Ce influențează clima orașului Râmnicu Sărat, care e departe de ocean?", "faptul că e departe de ocean: veri calde și ierni reci", ["curentul cald al Golfului", "musonul", "vânturile tropicale"], "Climatul cu nuanțe continentale: diferențe mari între vară și iarnă.")
    V.a(2, "4.2", "Ce temperatură record maximă s-a înregistrat în România?", "44,5 °C, la Ion Sion, în 1951", ["56,7 °C, la Ion Sion", "38 °C, la București", "50 °C, la Constanța"], "Recordul național e 44,5 °C (10 august 1951, Ion Sion, județul Brăila).", surse=S_RO)
    V.a(3, "4.2", "Ce temperatură record minimă s-a înregistrat în România?", "−38,5 °C, la Bod, în 1942", ["−89,2 °C, la Bod", "−10 °C, la Brașov", "−60 °C, pe Omu"], "Recordul național de frig e −38,5 °C (25 ianuarie 1942, Bod, județul Brașov).", surse=S_RO)
    V.a(2, "4.2", "Unde s-a înregistrat cea mai scăzută temperatură de pe Pământ?", "la stația Vostok, în Antarctica (−89,2 °C)", ["în Siberia (−20 °C)", "la Polul Nord (−200 °C)", "pe Everest (−10 °C)"], "−89,2 °C la Vostok, pe 21 iulie 1983.", surse=S_WMO)
    V.a(2, "4.2", "Unde s-a înregistrat oficial cea mai ridicată temperatură a aerului de pe Pământ?", "în Valea Morții, SUA (56,7 °C)", ["în Sahara (100 °C)", "la București (44,5 °C)", "la Ecuator (35 °C)"], "56,7 °C la Furnace Creek, Valea Morții, pe 10 iulie 1913.", surse=S_WMO)
    V.p(2, "2.1", "Atinge pe harta României orașul Râmnicu Sărat.", "romania", RS[0], RS[1], "Râmnicu Sărat", 40, "Râmnicu Sărat e în nord-estul județului Buzău, la contactul Subcarpaților de Curbură cu Câmpia Română.")
    V.a(3, "4.1", "Vrei să știi cum e clima orașului tău. De ce ai nevoie?", "de măsurătorile stației meteo pe cel puțin 30 de ani", ["de temperatura de azi", "de o fotografie a cerului", "de prognoza pe mâine"], "Clima se calculează din medii pe mulți ani.")
    V.a(2, "3.3", "Cum influențează clima viața oamenilor?", "decide ce plante se cultivă, ce haine purtăm și cum construim casele", ["nu are nicio influență", "decide doar culoarea caselor", "influențează doar animalele"], "Agricultura, construcțiile, îmbrăcămintea și turismul depind de climă.")
    V.a(2, "2.2", "Ce arată o hartă cu prognoza meteo pentru mâine?", "vremea așteptată: temperaturi, nori, ploi, vânt", ["clima pe 30 de ani", "relieful", "granițele județelor"], "Prognoza e despre vreme, pe termen scurt.")
    V.s(2, "1.2", "Asociază afirmația cu ce descrie: vremea sau clima.", [("„Ieri a nins la Buzău.”", "vremea din trecutul apropiat"), ("„În Sahara plouă foarte rar.”", "clima unui deșert"), ("„Mâine bate vântul.”", "prognoza vremii"), ("„La Ecuator e cald tot anul.”", "clima ecuatorială")], "Pe termen scurt – vremea; obișnuit, pe mulți ani – clima.")
    V.a(3, "1.2", "Ce înseamnă „schimbări climatice”?", "modificarea climei pe termen lung, de exemplu încălzirea medie a planetei în ultimele decenii", ["o zi mai caldă decât ieri", "schimbarea anotimpurilor", "o furtună puternică"], "Se vorbește de schimbări climatice când mediile pe zeci de ani se modifică.")

    # ================================================================ S20 Zonele climatice
    Z = Lectie(5, "V-S20-zonele-climatice-terrei-influenta", "Zonele climatice ale Terrei. Influența climei asupra geosferelor",
               "De ce în Kenya e cald tot anul, iar în Groenlanda e frig?",
               [("Zonele de climă", "Pământul primește căldură inegal de la Soare, după latitudine. Așa se formează zonele de climă.\nZona caldă – între cele două tropice, de o parte și de alta a Ecuatorului.\nZonele temperate – între tropice și cercurile polare, în ambele emisfere. România e în zona temperată nordică.\nZonele reci (polare) – dincolo de cercurile polare."),
                ("Cum e în fiecare zonă", "În zona caldă temperaturile sunt mari tot anul; lângă Ecuator plouă aproape zilnic, în deșerturi aproape deloc.\nÎn zonele temperate există patru anotimpuri.\nÎn zonele polare e frig aproape tot anul, cu zăpadă și gheață. Există zile polare și nopți polare."),
                ("Clima modelează celelalte învelișuri", "Clima influențează: apele (râuri mari unde plouă mult, ghețari unde e frig), relieful (vântul modelează dunele în deșert, gheața sapă văi la munte), solurile, plantele și animalele, și viața oamenilor.")],
               stiaica="La Polul Nord, în timpul verii, Soarele nu apune deloc aproape șase luni: aceasta e ziua polară.",
               ref=REF.format("Zonele climatice ale Terrei"))
    Z.a(1, "1.1", "În ce zonă de climă se află România?", "zona temperată nordică", ["zona caldă", "zona rece nordică", "zona temperată sudică"], "România e între Tropicul Racului și Cercul Polar de Nord.")
    Z.a(1, "1.1", "Între ce linii se află zona caldă?", "între Tropicul Racului și Tropicul Capricornului", ["între cele două cercuri polare", "între Polul Nord și Cercul Polar", "între Greenwich și Ecuator"], "Zona caldă e de o parte și de alta a Ecuatorului, până la tropice.")
    Z.a(2, "1.1", "Câte zone temperate există pe Pământ?", "două: una nordică și una sudică", ["una singură", "patru", "niciuna"], "Câte una în fiecare emisferă.")
    Z.o(2, "1.1", "Ordonează zonele de climă de la Ecuator spre Polul Nord.", ["zona caldă", "zona temperată nordică", "zona rece nordică"], "De la Ecuator spre Polul Nord", "Cald, temperat, rece.")
    Z.a(2, "3.2", "De ce e frig în zonele polare?", "pentru că razele Soarelui cad foarte înclinat și încălzesc puțin", ["pentru că acolo Soarele e mai mic", "pentru că acolo nu e aer", "pentru că e mai aproape de Lună"], "Razele înclinate se împrăștie pe o suprafață mare și încălzesc slab.")
    Z.a(2, "1.2", "Ce caracterizează zonele temperate?", "patru anotimpuri distincte", ["cald și ploios tot anul", "gheață tot anul", "noapte șase luni"], "Primăvara, vara, toamna, iarna.")
    Z.s(2, "1.2", "Asociază zona de climă cu un loc din ea.", [("zona caldă", "Bazinul Amazonului"), ("zona temperată nordică", "România"), ("zona rece nordică", "Groenlanda"), ("zona rece sudică", "Antarctica")], "Fiecare zonă are locurile ei tipice.")
    Z.e(2, "2.1", "Pune pe hartă etichetele locurilor, după zona de climă.", [("ro", "România – zona temperată", 46, 25), ("am", "Amazonia – zona caldă", -4, -62), ("gr", "Groenlanda – zona rece", 72, -40), ("an", "Antarctica – zona rece", -80, 30)], "România e în zona temperată, Amazonia în zona caldă, Groenlanda și Antarctica în zonele reci.", harta="lume")
    Z.p(2, "2.1", "Atinge pe hartă un loc din zona caldă: Bazinul Congo (Africa).", "lume", -1, 22, "Bazinul Congo", 1200, "Bazinul Congo e pe Ecuator, în zona caldă.")
    Z.p(3, "2.1", "Atinge pe hartă Groenlanda, un loc din zona rece.", "lume", 72, -40, "Groenlanda", 1200, "Groenlanda e o insulă imensă, acoperită de gheață, la nord-est de America de Nord.")
    Z.a(2, "1.2", "Ce este noaptea polară?", "perioada în care Soarele nu răsare deloc, timp de zile sau luni, dincolo de cercul polar", ["o noapte foarte scurtă", "o noapte fără Lună", "noaptea de la Ecuator"], "Iarna, la poli, Soarele nu apare deasupra orizontului.")
    Z.adev(2, "1.2", "În zona caldă e cald tot anul, dar nu peste tot plouă mult.", True, "Adevărat: lângă Ecuator plouă mult, dar în deșerturi ca Sahara plouă foarte rar.")
    Z.adev(2, "1.2", "În zonele polare există patru anotimpuri la fel de lungi ca la noi.", False, "Fals: acolo iarna e foarte lungă, iar vara scurtă și rece.")
    Z.a(3, "3.2", "Cum influențează clima râurile?", "unde plouă mult râurile sunt mari și bogate în apă; în deșert sunt rare sau seacă", ["nu are nicio influență", "râurile sunt la fel peste tot", "râurile curg doar în zona rece"], "Amazonul e uriaș pentru că bazinul lui primește foarte multă ploaie.")
    Z.a(3, "3.2", "Cum influențează clima relieful, în deșerturi?", "vântul transportă nisipul și formează dune", ["ghețarii sapă văi", "valurile formează faleze", "râurile formează delte"], "În deșert, vântul e principalul agent care modelează relieful.")
    Z.a(3, "3.2", "Cum influențează clima relieful, în munții foarte înalți și reci?", "ghețarii sapă văi și căldări glaciare", ["vântul formează dune", "lava acoperă munții", "valurile sapă peșteri"], "Gheața în mișcare roade rocile.")
    Z.a(2, "3.3", "Cum influențează clima plantele?", "în zona caldă și umedă cresc păduri dese; în zona rece, doar mușchi și licheni", ["plantele sunt la fel peste tot", "plantele nu au nevoie de căldură", "doar deșertul are plante"], "Căldura și umezeala decid ce plante cresc.")
    Z.s(3, "3.2 3.3", "Asociază zona de climă cu ce influențează.", [("zona caldă și umedă", "păduri ecuatoriale"), ("zona caldă și uscată", "deșerturi cu dune"), ("zona temperată", "păduri de foioase și stepe"), ("zona rece", "gheață și tundră")], "Clima decide peisajul.")
    Z.l(2, "1.1", "Completează.", "Zona caldă e între [tropice]; zonele reci sunt dincolo de [cercurile polare].", ["meridiane", "Greenwich"], "Tropicele și cercurile polare sunt limitele zonelor de climă.")
    Z.l(2, "1.1", "Completează.", "România se află în emisfera [nordică], în zona [temperată].", ["sudică", "caldă"], "Emisfera nordică, zona temperată.")
    Z.a(2, "3.3", "Cum se adaptează casele din zona rece?", "au pereți groși și ferestre mici, ca să păstreze căldura", ["sunt făcute din frunze", "nu au acoperiș", "au pereți subțiri și ferestre uriașe"], "Construcțiile se adaptează la climă.")
    Z.a(2, "3.3", "Ce animal trăiește în zona rece nordică?", "ursul polar", ["girafa", "cămila", "zebra"], "Ursul polar are blană deasă și un strat gros de grăsime.")
    Z.a(2, "3.3", "Ce animal e adaptat la deșert?", "cămila", ["pinguinul", "ursul polar", "foca"], "Cămila rezistă mult fără apă.")
    Z.a(3, "1.2", "Pe Ecuator, la 5 000 m altitudine, pe muntele Kilimanjaro, e zăpadă. De ce?", "pentru că temperatura scade cu altitudinea, chiar și în zona caldă", ["pentru că Kilimanjaro e lângă pol", "pentru că acolo e iarnă tot anul pe tot continentul", "pentru că zăpada e adusă de oameni"], "Altitudinea poate crea condiții reci chiar la Ecuator.")
    Z.a(2, "2.1", "Pe ce continent se află cea mai mare parte a zonei reci sudice?", "Antarctica", ["Africa", "Australia", "America de Sud"], "Antarctica e aproape toată dincolo de Cercul Polar de Sud.")
    Z.a(3, "3.2", "Dacă te deplasezi de la Ecuator spre Polul Sud, prin ce zone treci, în ordine?", "zona caldă, zona temperată sudică, zona rece sudică", ["zona rece, zona caldă, zona temperată", "doar zona caldă", "zona temperată nordică, apoi zona rece nordică"], "Același tipar, în oglindă, în emisfera sudică.")
    Z.g(3, "2.3", "Graficul arată temperatura medie anuală în trei locuri imaginare. Care e, probabil, în zona rece?", grafic("bare", "Temperatura medie anuală (date imaginare)", [("Locul A", 26), ("Locul B", 10), ("Locul C", -18)], "°C"), "Locul C", ["Locul A", "Locul B", "toate"], "−18 °C media anuală arată un loc foarte rece; A e cald, B temperat.")
    Z.a(2, "3.3", "Ce înseamnă pentru agricultură zona temperată?", "se pot cultiva grâu, porumb, floarea-soarelui, cu recolte vara și toamna", ["se cultivă orice, de patru ori pe an", "nu se poate cultiva nimic", "se cultivă doar banane"], "Anotimpurile decid calendarul lucrărilor agricole.")
    Z.a(1, "1.1", "Ce linie împarte Pământul în emisfera nordică și emisfera sudică?", "Ecuatorul", ["meridianul de origine", "Tropicul Racului", "Cercul Polar de Nord"], "Ecuatorul are latitudinea 0°.")
    Z.a(3, "3.2", "De ce în Australia e vară în decembrie?", "pentru că e în emisfera sudică, unde anotimpurile sunt inversate față de noi", ["pentru că e mai aproape de Soare", "pentru că e pe Ecuator", "pentru că nu are iarnă niciodată"], "Când emisfera nordică e înclinată departe de Soare, cea sudică primește mai multă lumină.")

    # ================================================================ S22 Expediție: vremea și clima în orizontul local
    E = Expeditie(5, "V-S22-aplicatii-practice-clima-vremea", "Expediție: vremea din orizontul meu",
                  "Ce fenomene meteorologice periculoase pot apărea la Râmnicu Sărat și cum ne protejăm?",
                  ref=REF.format("Aplicații practice: Clima, vremea și activitatea umană în orizontul local"))
    E.a(1, "4.1", "Ce instrumente îți trebuie pentru o mini-stație meteo la școală?", "termometru, pluviometru (un vas gradat) și o giruetă", ["telescop și microscop", "busolă și riglă", "cântar și ceas"], "Cu ele măsori temperatura, ploaia și direcția vântului.")
    E.a(2, "4.1", "Faci un pluviometru dintr-o sticlă tăiată. Unde îl așezi?", "în loc deschis, departe de copaci și acoperișuri", ["sub streașină", "în clasă", "sub un copac"], "Ploaia trebuie să cadă liber în vas.")
    E.pas("1. Mini-stația meteo", "Construiește un pluviometru dintr-o sticlă de plastic tăiată și o riglă lipită pe ea. Așază-l în curte, împreună cu un termometru la umbră.")
    E.g(2, "4.2 2.3", "Ai notat temperatura de la ora 12, timp de 5 zile (date imaginare). Care zi a fost cea mai rece?", grafic("bare", "Temperatura la ora 12 (exemplu de jurnal)", [("luni", 8), ("marți", 5), ("miercuri", 2), ("joi", 6), ("vineri", 9)], "°C"), "miercuri", ["luni", "vineri", "joi"], "Miercuri: 2 °C.")
    E.pas("2. Jurnalul vremii", "Timp de 5 zile, la aceeași oră, notează temperatura, cerul (senin, noros, acoperit), vântul (calm, slab, puternic) și dacă a plouat.",
          jurnal="Fă un tabel cu cele 5 zile și scrie ce ai observat. Care a fost ziua cea mai caldă?")
    E.s(2, "4.3", "Asociază fenomenul periculos cu măsura de protecție.", [("canicula", "stai la umbră, bei apă, eviți soarele între 11 și 17"), ("viscolul", "nu pleci la drum, păstrezi provizii"), ("poleiul", "mergi încet, cu încălțăminte antiderapantă"), ("grindina", "te adăpostești într-o clădire și pui mașina la adăpost")], "Fiecare fenomen are regulile lui.")
